package com.bank.thrift;

import java.util.logging.Logger;

// Interleaves query "ticks" from concurrent sessions so one big query cannot block others.
class FairScheduler {
    private static final Logger log = Logger.getLogger(FairScheduler.class.getName());

    // Simulates running two queries fairly: each gets a turn per round.
    void runFairly(String sessionA, int costA, String sessionB, int costB) {
        int doneA = 0, doneB = 0;
        int round = 0;
        while (doneA < costA || doneB < costB) {
            round++;
            if (doneA < costA) { doneA++; }
            if (doneB < costB) { doneB++; }
            if (round % 5 == 0) {
                final int a = doneA, b = doneB;
                log.fine(() -> "FAIR round " + round + ": " + sessionA + "=" + a + "/" + costA
                        + ", " + sessionB + "=" + b + "/" + costB);
            }
        }
        log.info(() -> "FAIR scheduling complete: both " + sessionA + " and " + sessionB
                + " progressed concurrently (neither starved)");
    }
}
