package com.bank.thrift;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.logging.Logger;

// A persistent, shared Spark SQL service exposed over a JDBC-like protocol.
class ThriftServer {
    private static final Logger log = Logger.getLogger(ThriftServer.class.getName());

    private final Map<String, TradeTable> catalog = new HashMap<>();
    private final Set<String> cachedTables = new HashSet<>();  // SHARED cache across sessions
    private final FairScheduler scheduler = new FairScheduler();
    private int sessionCounter = 0;

    void start(int port) {
        log.info(() -> "Spark Thrift Server started on port " + port + " (HiveServer2 protocol)");
    }

    void registerTable(TradeTable table) {
        catalog.put(table.name, table);
        log.info(() -> "Registered table in shared catalog: " + table.name + " (" + table.rows.size() + " rows)");
    }

    // A BI tool opens a JDBC session.
    JdbcSession connect(String user) {
        String sessionId = "session-" + (++sessionCounter) + "(" + user + ")";
        log.info(() -> "JDBC client connected: " + sessionId);
        return new JdbcSession(sessionId, this);
    }

    // Execute SQL. Reading a cached table is faster; CACHE populates the SHARED cache.
    long executeQuery(String sessionId, String sql) {
        String lower = sql.toLowerCase();
        if (lower.startsWith("cache table")) {
            String t = sql.substring("cache table".length()).trim();
            cachedTables.add(t);
            log.info(() -> sessionId + " cached table " + t + " in the SHARED cache");
            return 0;
        }
        String table = parseFrom(lower);
        TradeTable t = catalog.get(table);
        if (t == null) { log.warning(() -> sessionId + " queried missing table " + table); return -1; }
        boolean cached = cachedTables.contains(table);
        long cost = cached ? t.rows.size() / 10 : t.rows.size(); // cached = 10x cheaper
        log.info(() -> sessionId + " ran [" + sql + "] over " + table
                + (cached ? " (served from SHARED cache, fast)" : " (full scan)"));
        return cost;
    }

    FairScheduler scheduler() { return scheduler; }

    private String parseFrom(String lowerSql) {
        int idx = lowerSql.indexOf("from ");
        if (idx < 0) return "";
        String rest = lowerSql.substring(idx + 5).trim();
        int sp = rest.indexOf(' ');
        return sp < 0 ? rest : rest.substring(0, sp);
    }
}
