package com.bank.thrift;

import java.util.logging.Logger;

// Represents one connected BI client (Tableau, beeline, DBeaver) running SQL.
class JdbcSession {
    private static final Logger log = Logger.getLogger(JdbcSession.class.getName());

    private final String sessionId;
    private final ThriftServer server;

    JdbcSession(String sessionId, ThriftServer server) {
        this.sessionId = sessionId;
        this.server = server;
    }

    String id() { return sessionId; }

    long sql(String statement) {
        return server.executeQuery(sessionId, statement);
    }
}
