package com.bank.thrift;

import java.util.logging.Logger;

public class ThriftDemo {
    private static final Logger log = Logger.getLogger(ThriftDemo.class.getName());

    public static void main(String[] args) {
        ThriftServer server = new ThriftServer();
        server.start(10000);

        TradeTable trades = new TradeTable("trades");
        trades.loadRows(100_000);
        server.registerTable(trades);

        // Two BI tools connect — they SHARE the same server, cache, and compute.
        JdbcSession tableau = server.connect("risk_analyst_priya");
        JdbcSession dbeaver = server.connect("risk_analyst_rajesh");

        // Priya's query caches the table in the SHARED cache.
        tableau.sql("CACHE TABLE trades");
        long c1 = tableau.sql("SELECT count(*) FROM trades WHERE amount > 50000");
        log.info(() -> "Priya query cost = " + c1);

        // Rajesh benefits from Priya's cache without caching anything himself.
        long c2 = dbeaver.sql("SELECT symbol, count(*) FROM trades GROUP BY symbol");
        log.info(() -> "Rajesh query cost = " + c2 + " (reused SHARED cache populated by Priya)");

        // Fair scheduling: a big query and a small query run concurrently without starvation.
        server.scheduler().runFairly(tableau.id(), 100, dbeaver.id(), 10);
    }
}
